def nthMagicalNumber(n: int, a: int, b: int) -> int:
    lo = 2
    hi = 10**100
    res = 0

    while lo <= hi:
        mid = (lo + hi) // 2

        # Calculate gcd_ab = gcd(a, b)
        if a % b == 0:
            gcd_ab = b
        elif b % a == 0:
            gcd_ab = a
        else:
            gcd_ab = None

        # Calculate lcm_ab = (a * b) // gcd_ab
        lcm_ab = (a * b) // gcd_ab

        # Check if mid // a + mid // b - mid // lcm_ab >= n
        count = mid // a + mid // b - mid // lcm_ab

        if count >= n:
            res = mid
            hi = mid - 1
        else:
            lo = mid + 1

    return res % (10**9 + 7)
